<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import ConfiguredChart from './components/ConfiguredChart.vue';
import CampusMap from './components/CampusMap.vue';
import type { ActivityPath } from './types';
type Metric={code:string;name:string;value:number|null;unit:string;data_class:string;quality_status:string};
type Entry={label:string;url:string;params:Record<string,string|number>};
type System={id:string;name:string;kind:string;status:'READY'|'DEGRADED'|'OFFLINE'|'UNCONFIGURED';message:string;observed_at:string|null;data_class:string;metrics:Metric[];alerts:{code:string;level:string;title:string;object_id:string|null;occurred_at:string|null}[];series:{code:string;name:string;unit:string;points:{x:number;p10:number;p50:number;p90:number}[]}[];resources:Record<string,unknown>;entry:Entry};
type Overview={schema_version:string;campus:{id:string;name:string};generated_at:string;observation_time:string|null;systems:System[];map:{building_results:any[];edge_boxes:any[]};visualizations:{prediction:{x:number;p10:number;p50:number;p90:number}[];building_ranking:{name:string;value:number}[];renewable_ratio:number|null;energy_flow:{nodes:{name:string}[];links:{source:string;target:string;value:number}[]};system_health:{name:string;value:number;status:string}[];data_notice:string};summary:Record<string,number>;contract_notice:string};
type ChartDefinition={id:string;title:string;type:'line'|'bar'|'gauge'|'sankey'|'radar';data_path:string;unit:string;bindings:any;refresh_seconds:number;interactions:string[];data_class:string};
const overview=ref<Overview>(),chartDefinitions=ref<ChartDefinition[]>([]),mapPaths=ref<ActivityPath[]>([]),error=ref(''),busy=ref(false),now=ref(new Date()),chartPickerOpen=ref(false);
let refreshTimer:ReturnType<typeof setInterval>|undefined,clockTimer:ReturnType<typeof setInterval>|undefined;const abort=new AbortController();
const statusText={READY:'正常',DEGRADED:'降级',OFFLINE:'离线',UNCONFIGURED:'未配置'};
const fmt=(value:number|null|undefined)=>value==null?'—':value.toLocaleString('zh-CN',{maximumFractionDigits:1});
const time=(value:string|null|undefined)=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'尚无时间';
async function refresh(force=false){if(busy.value)return;busy.value=true;try{const [response,library,pathResponse]=await Promise.all([fetch(`/api/bff/overview?force=${force}`,{signal:abort.signal}),fetch('/api/bff/chart-library',{signal:abort.signal}),fetch('/api/activities/showcase-paths',{signal:abort.signal})]);if(!response.ok||!library.ok)throw new Error(`BFF返回 ${response.status}/${library.status}`);overview.value=await response.json();chartDefinitions.value=(await library.json()).definitions||[];if(pathResponse.ok){const result=await pathResponse.json();mapPaths.value=Array.isArray(result.paths)?result.paths:[]}error.value=''}catch(e){if(!abort.signal.aborted)error.value=(e as Error).message}finally{busy.value=false}}
function enter(entry:Entry){window.open(entry.url,'_blank','noopener,noreferrer')}
const chartMode=ref(localStorage.getItem('dashboard-chart-definition')||'simulation_interval');
const chartModes=computed(()=>chartDefinitions.value.map(item=>({id:item.id,name:{line:'趋势',bar:'排行',gauge:'占比',sankey:'流向',radar:'状态'}[item.type]})));
const activeChart=computed(()=>chartDefinitions.value.find(item=>item.id===chartMode.value));
function selectChart(id:string){chartMode.value=id;localStorage.setItem('dashboard-chart-definition',id);chartPickerOpen.value=false}
const allAlerts=computed(()=>overview.value?.systems.flatMap(s=>s.alerts.map(a=>({...a,system:s.name})))||[]);
const highlightedPathId=computed(()=>mapPaths.value.reduce((best,item)=>Number(item.route_distance_m||0)>Number(best?.route_distance_m||0)?item:best,mapPaths.value[0])?.global_id);
onMounted(()=>{void refresh();clockTimer=setInterval(()=>now.value=new Date(),1000);refreshTimer=setInterval(()=>{if(!document.hidden)void refresh()},30000)});
onBeforeUnmount(()=>{abort.abort();if(clockTimer)clearInterval(clockTimer);if(refreshTimer)clearInterval(refreshTimer)});
</script>
<template>
<div class="gateway-screen">
  <header class="gateway-header"><div class="brand">碳中和 · 综合数据中心<small>UNIFIED CARBON DATA BFF</small></div><div class="title"><h1>{{overview?.campus.name||'湖北经济学院智慧低碳校园'}}</h1><span>综合总览与验收入口</span></div><button :disabled="busy" @click="refresh(true)">{{busy?'聚合中':'刷新聚合结果'}}</button></header>
  <div class="gateway-meta"><b><i/>BFF 服务在线</b><span>系统时间 {{now.toLocaleString('zh-CN',{hour12:false})}}</span><span>数据时间 {{time(overview?.observation_time)}}</span><span>契约 V{{overview?.schema_version||'—'}}</span></div>
  <p v-if="error" class="gateway-error">聚合接口读取失败：{{error}}。未使用模拟结果替代。</p>
  <section class="summary-strip"><article><small>接入系统</small><b>{{overview?.summary.system_count??'—'}}</b><i>个</i></article><article class="ok"><small>正常服务</small><b>{{overview?.summary.READY??'—'}}</b><i>个</i></article><article class="warn"><small>降级服务</small><b>{{overview?.summary.DEGRADED??'—'}}</b><i>个</i></article><article class="danger"><small>离线服务</small><b>{{overview?.summary.OFFLINE??'—'}}</b><i>个</i></article><article><small>待配置系统</small><b>{{overview?.summary.UNCONFIGURED??'—'}}</b><i>个</i></article></section>
  <main class="gateway-main">
    <section class="system-grid"><article v-for="(system,index) in overview?.systems" :key="system.id" class="system-card" :class="system.status.toLowerCase()"><header><span>0{{index+1}}</span><div><small>{{system.kind}}</small><h2>{{system.name}}</h2></div><em>{{statusText[system.status]}}</em></header><p>{{system.message}}</p><div class="metric-grid"><div v-for="metric in system.metrics.slice(0,4)" :key="metric.code"><small>{{metric.name}}</small><b>{{fmt(metric.value)}}<i>{{metric.unit}}</i></b><span>{{metric.quality_status==='UNKNOWN'?'待接入':metric.data_class==='OBSERVED'?'实测':'模型结果'}}</span></div></div><footer><span>更新时间 {{time(system.observed_at)}}</span><button @click="enter(system.entry)">{{system.entry.label}} →</button></footer></article></section>
    <section class="gateway-map"><header><div><small>GIS · SPATIAL OVERVIEW</small><h2>校园排放热点总览</h2></div><span>建筑热力 · 边缘盒子位置 · 跨镜路径（示范）</span></header><CampusMap :rows="overview?.map?.building_results||[]" :paths="mapPaths" :selected-global-id="highlightedPathId" :devices="[]"/><p v-if="!overview?.map?.edge_boxes?.length">边缘盒子坐标尚未接入；配置接口后叠加真实位置，不使用传感器位置替代。</p></section>
    <aside class="overview-side"><section class="interval-panel multimodal-panel"><header><div><small>MULTIMODAL CHART LIBRARY</small><h2>{{activeChart?.title||'多模态图表库'}}</h2></div><button class="choose-chart" @click="chartPickerOpen=!chartPickerOpen">选择图表</button></header><div v-if="chartPickerOpen" class="chart-picker"><header><b>选择图表组件</b><button @click="chartPickerOpen=false">×</button></header><div><button v-for="mode in chartModes" :key="mode.id" :class="{active:chartMode===mode.id}" @click="selectChart(mode.id)"><i :class="`preview-${chartDefinitions.find(x=>x.id===mode.id)?.type}`"><span/><span/><span/></i><b>{{chartDefinitions.find(x=>x.id===mode.id)?.title}}</b><small>{{chartDefinitions.find(x=>x.id===mode.id)?.type.toUpperCase()}} · {{mode.name}}</small></button></div></div><ConfiguredChart v-if="overview&&activeChart" :definition="activeChart" :source="overview"/><div v-else class="gateway-empty">等待图表定义与统一数据</div><p v-if="activeChart">{{activeChart.type.toUpperCase()}} · {{activeChart.data_path}} · {{activeChart.unit}} · {{activeChart.refresh_seconds}}秒刷新</p></section><section class="alert-panel"><header><small>UNIFIED EVENTS</small><h2>系统运行事件</h2></header><div v-if="allAlerts.length" class="alert-list"><article v-for="alert in allAlerts" :key="`${alert.system}-${alert.code}-${alert.object_id}`"><i/><div><b>{{alert.title}}</b><span>{{alert.system}} · {{alert.object_id||'系统级'}}</span></div><time>{{time(alert.occurred_at)}}</time></article></div><div v-else class="gateway-empty">当前无系统运行事件</div></section></aside>
  </main>
  <footer class="contract-footer"><b>统一取数层</b><span>{{overview?.contract_notice||'上游数据统一口径后供大屏展示。'}}</span><em>下钻自动携带 campus_id / site_id / run_id / task_id</em></footer>
</div>
</template>
